EXEC sys.sp_query_store_flush_db;
SELECT q.query_id,p.plan_id,SUM(rs.count_executions) AS execucoes,
 SUM(rs.avg_duration*rs.count_executions)/NULLIF(SUM(rs.count_executions),0) AS media_us
 FROM sys.query_store_query_text t
 JOIN sys.query_store_query q ON q.query_text_id=t.query_text_id
 JOIN sys.query_store_plan p ON p.query_id=q.query_id
 JOIN sys.query_store_runtime_stats rs ON rs.plan_id=p.plan_id
 WHERE t.query_sql_text LIKE N'SELECT SUM(valor) AS ForgeA28Probe%'
 GROUP BY q.query_id,p.plan_id ORDER BY q.query_id,p.plan_id;
