BEGIN TRY
 BEGIN TRAN;
 UPDATE #Teste SET qtd=qtd-2 WHERE id=1 AND qtd>=2;
 IF @@ROWCOUNT<>1 THROW 50036,N'Retirada esperada não foi aplicada.',1;
 IF (SELECT qtd FROM #Teste WHERE id=1)<>3 THROW 50036,N'Estado inesperado.',1;
 ROLLBACK;
 IF (SELECT qtd FROM #Teste WHERE id=1)<>5 THROW 50036,N'Rollback não conferiu.',1;
